        String mostPopularColor = Collections.max(colorCounts.keySet());
        int maxCount = Collections.max(colorCounts.values());
        for (Car car : cars) {
            if (car.getColor().equals(mostPopularColor) && Collections.frequency(cars, car) == maxCount) {
                return car;
            }
        }
        return null; // Return null if no car has the most popular color
    }
}
